glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv0;
out vec4 color;
vec4 vert () {
  vec4 p = vec4(a_position, 1.0);
  #if USE_LOCAL
    p = cc_matWorld * p;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return cc_matViewProj * p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
in vec2 uv0;
in vec4 color;
layout(std140) uniform RocketConstants { vec4 tint; vec4 fxParams; vec4 dissolveParams; vec4 magicParams; };
uniform sampler2D noiseTexture;
uniform sampler2D maskTexture;
uniform sampler2D cc_spriteTexture;
vec4 frag () {
  vec2 uv = uv0;
  float age = fxParams.x;
  vec2 noiseUV = fract(uv + vec2(0.0, age * dissolveParams.w));
  float noise = texture(noiseTexture, noiseUV).r;
  uv += (vec2(noise) - 0.5) * dissolveParams.z * fxParams.y;
  vec4 texel = CCSampleWithAlphaSeparated(cc_spriteTexture, clamp(uv, vec2(0.0), vec2(1.0)));
  float alpha = texel.a;
  if (fxParams.z > 0.5) alpha *= texture(maskTexture, uv0).r;
  if (fxParams.w > 0.5) {
    float threshold = mix(-dissolveParams.y, 1.0, age) + dissolveParams.x;
    alpha *= smoothstep(threshold, threshold + max(0.03, dissolveParams.y), noise);
  }
  vec3 lightColor = texel.rgb * tint.rgb * color.rgb;
  if (magicParams.x > 0.5) lightColor = mix(lightColor, vec3(1.0, 1.0, 0.98), smoothstep(0.7, 1.0, texel.a) * 0.32);
  return vec4(lightColor, alpha * tint.a * color.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
#if USE_LOCAL
  uniform highp mat4 cc_matWorld;
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 uv0;
varying vec4 color;
vec4 vert () {
  vec4 p = vec4(a_position, 1.0);
  #if USE_LOCAL
    p = cc_matWorld * p;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return cc_matViewProj * p;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
varying vec2 uv0;
varying vec4 color;
  uniform vec4 tint;
  uniform vec4 fxParams;
  uniform vec4 dissolveParams;
  uniform vec4 magicParams;
uniform sampler2D noiseTexture;
uniform sampler2D maskTexture;
uniform sampler2D cc_spriteTexture;
vec4 frag () {
  vec2 uv = uv0;
  float age = fxParams.x;
  vec2 noiseUV = fract(uv + vec2(0.0, age * dissolveParams.w));
  float noise = texture2D(noiseTexture, noiseUV).r;
  uv += (vec2(noise) - 0.5) * dissolveParams.z * fxParams.y;
  vec4 texel = CCSampleWithAlphaSeparated(cc_spriteTexture, clamp(uv, vec2(0.0), vec2(1.0)));
  float alpha = texel.a;
  if (fxParams.z > 0.5) alpha *= texture2D(maskTexture, uv0).r;
  if (fxParams.w > 0.5) {
    float threshold = mix(-dissolveParams.y, 1.0, age) + dissolveParams.x;
    alpha *= smoothstep(threshold, threshold + max(0.03, dissolveParams.y), noise);
  }
  vec3 lightColor = texel.rgb * tint.rgb * color.rgb;
  if (magicParams.x > 0.5) lightColor = mix(lightColor, vec3(1.0, 1.0, 0.98), smoothstep(0.7, 1.0, texel.a) * 0.32);
  return vec4(lightColor, alpha * tint.a * color.a);
}
void main() { gl_FragColor = frag(); }
